#!/bin/sh
# layer-2 load audit -- csharp -- generated by
# Research/data_representation/audit_generate.py . Do not hand-edit; regenerate.
# Every line of /out/l2_csharp.txt is FACT_ID|RESULT, FACT_ID being
# <form>.<representation>.<probe>.
set -u
ROOT=/work/l2_csharp
rm -rf "$ROOT"; mkdir -p "$ROOT"
export HOME=/work
export GOFLAGS=-mod=mod
export GO111MODULE=off
export GOCACHE=/work/.gocache
export GOPATH=/work/.gopath
export PATH=/persist/dart-sdk/bin:$PATH

# swift's binaries want an ncurses name the image does not ship under; the fix
# is per-container, so every script that may touch swift re-applies it.
ncurses_fix() {
  if [ -f /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 ]; then
    ln -sf /usr/lib/x86_64-linux-gnu/libncursesw.so.6.6 \
       /usr/lib/x86_64-linux-gnu/libncurses.so.6 2>/dev/null
    ldconfig 2>/dev/null
  fi
}
ncurses_fix

OUT=/out/l2_csharp.txt
: > "$OUT"
echo "=== layer-2 load audit -- csharp ==="
date -u +%Y-%m-%dT%H:%M:%SZ
if ! test -x /persist/dotnet/dotnet >/dev/null 2>&1; then
  echo "csharp: TOOLCHAIN ABSENT -- nothing run"
  echo "__ABSENT__|<absent>" >> "$OUT"
  exit 0
fi


# ---- nothing.string? (null reference).null
D=$ROOT/p1; mkdir -p "$D"; cd "$D"
cat > Program.cs <<'L2_SRC_EOF'

public class Program {
  public static void Main() {
    string? v = null;
    System.Console.WriteLine("nothing.string? (null reference).null" + "|" + (v == null ? "null" : v));
  }
}
L2_SRC_EOF
V=ok
if ! timeout 180 /persist/dotnet-csc-build.sh > build.out 2> build.err; then V="<compile-error>"; fi
if [ "$V" = ok ]; then
  if timeout 30 /persist/dotnet-csc-run.sh > run.out 2> run.err; then :; else
    V="<aborted>"
  fi
  grep -F "nothing.string? (null reference).null|" run.out >> "$OUT" || V="${V}"
fi
grep -qF "nothing.string? (null reference).null|" "$OUT" || echo "nothing.string? (null reference).null|$V" >> "$OUT"

